Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='typsteditor', at=datetime(2026, 10, 2, 0, 0, 0), actor='owner', title="A todo's body and detail are edited as Typst, with highlighting, completion and a live preview", body='*A todo\'s body and detail are edited as Typst* (2026-10-02, the owner: "I know how to write typst and I do expect syntax highlighting and live recompile while editing"; `web/src/typst/editor.ts`, WEB-SPEC §3.14): a native textarea over its shaded twin (typst-wasm\'s `highlight`), typst-ide\'s completion and hover, the diagnostics under the field with their spans marked, and a preview compiled once per frame in a worker running the same `Project.restricted()` the box admits a text by, checked by the box\'s tripwire before it is parsed, and terminated when a compile outlives two seconds. The box is still the one that refuses; the editor shows the same words sooner.', rationale='The owner, 2026-10-02: "I know how to write typst and I do expect syntax highlighting and live recompile while editing".', supersedes=()))